570	+//! `callisto init`'s reading of an existing Changesets `.changeset/config.json`.
571	+
572	+use std::path::{Path, PathBuf};
573	+
574	+use callisto_model::{BranchName, Diagnostic, DiagnosticCode, DiagnosticSeverity, Ecosystem};
575	+use globset::GlobBuilder;
576	+use serde_json::{Map, Value};
577	+
578	+use super::{InitAnswers, InitFacts, Versioning};
579	+
580	+/// One `[[fixed-group]]` carried over from a Changesets `fixed` group.
581	+#[derive(Clone, Debug, PartialEq, Eq)]
582	+pub struct FixedGroup {
583	+    pub name: String,
584	+    /// Qualified package ids.
585	+    pub members: Vec<String>,
586	+}
587	+
588	+/// What a Changesets config means for `callisto init`.
589	+#[derive(Clone, Debug, Default)]
590	+pub struct Migration {
591	+    path: PathBuf,
592	+    fixed_groups: Vec<FixedGroup>,
593	+    /// `fixed` members that matched no npm package.
594	+    fixed_unmatched: Vec<String>,
595	+    /// `baseBranch`, which becomes the generated workflow's branch filter.
596	+    pub base_branch: Option<BranchName>,
597	+    /// Scoped npm packages that would publish as public.
598	+    pub public_scoped: Vec<String>,
599	+    /// One warning per key `init` does not carry over.
600	+    pub diagnostics: Vec<Diagnostic>,
601	+}
602	+
603	+/// A top-level `config.json` key, so each one is handled in one exhaustive match.
604	+enum Key<'a> {
605	+    Fixed,
606	+    Linked,
607	+    Ignore,
608	+    Access,
609	+    BaseBranch,
610	+    UpdateInternalDependencies,
611	+    Schema,
612	+    Other(&'a str),
613	+}
614	+
615	+impl<'a> From<&'a str> for Key<'a> {
616	+    fn from(key: &'a str) -> Self {
617	+        match key {
618	+            "fixed" => Self::Fixed,
619	+            "linked" => Self::Linked,
620	+            "ignore" => Self::Ignore,
621	+            "access" => Self::Access,
622	+            "baseBranch" => Self::BaseBranch,
623	+            "updateInternalDependencies" => Self::UpdateInternalDependencies,
624	+            "$schema" => Self::Schema,
625	+            other => Self::Other(other),
626	+        }
627	+    }
628	+}
629	+
630	+fn config_path(root: &Path) -> PathBuf {
631	+    root.join(".changeset/config.json")
632	+}
633	+
634	+/// The config's top-level object; `None` when the file is absent, unreadable, or not a JSON object.
635	+fn read(root: &Path) -> Option<Map<String, Value>> {
636	+    let text = std::fs::read_to_string(config_path(root)).ok()?;
637	+    match serde_json::from_str(&text) {
638	+        Ok(Value::Object(config)) => Some(config),
639	+        _ => None,
640	+    }
641	+}
642	+
643	+fn branch(value: &Value) -> Option<BranchName> {
644	+    BranchName::from_full_ref(&format!("refs/heads/{}", value.as_str()?))
645	+}
646	+
647	+/// Reads `root`'s Changesets config against the detected packages.
648	+pub fn migrate(root: &Path, facts: &InitFacts) -> Migration {
649	+    let Some(config) = read(root) else {
650	+        return Migration::default();
651	+    };
652	+    let mut migration = Migration {
653	+        path: config_path(root),
654	+        ..Migration::default()
655	+    };
656	+    for (key, value) in &config {
657	+        let nothing_to_drop = value.as_array().is_some_and(Vec::is_empty);
658	+        match Key::from(key.as_str()) {
659	+            Key::Fixed => migration.translate_fixed(value, facts),
660	+            Key::Linked if nothing_to_drop => {}
661	+            Key::Linked => migration.warn(
662	+                "linked",
663	+                "is not translated: callisto bumps every member of a linked group on each release, Changesets only \
664	+                 the members with changesets; write a `[[linked-group]]` by hand to get that",
665	+            ),
666	+            Key::Ignore if nothing_to_drop => {}
667	+            Key::Ignore => migration.warn(
668	+                "ignore",
669	+                "is not translated: ignored packages are still versioned and released; set `publish-to = [\"none\"]` \
670	+                 on a package to stop its publishing",
671	+            ),
672	+            Key::Access => {}
673	+            Key::BaseBranch => match branch(value) {
674	+                Some(base) => migration.base_branch = Some(base),
675	+                None => migration.warn("baseBranch", "is not a branch name and is ignored"),
676	+            },
677	+            Key::UpdateInternalDependencies => migration.warn(
678	+                "updateInternalDependencies",
679	+                "is not honoured; callisto always raises the ranges of dependents released with the dependency",
680	+            ),
681	+            Key::Schema => {}
682	+            Key::Other(other) => migration.warn(other, "is not honoured; callisto has no equivalent"),
683	+        }
684	+    }
685	+    // Changesets publishes scoped packages as restricted unless `access` is `public`.
686	+    if config.get("access").and_then(Value::as_str) != Some("public") {
687	+        migration.public_scoped = facts
688	+            .packages
689	+            .iter()
690	+            .filter(|package| !package.platform && package.publishes_public_by_default())
691	+            .map(|package| package.id.clone())
692	+            .collect();
693	+        if !migration.public_scoped.is_empty() {
694	+            let packages = migration.public_scoped.join(", ");
695	+            migration.warn(
696	+                "access",
697	+                &format!(
698	+                    "is restricted or absent, so Changesets would publish scoped packages privately; callisto \
699	+                     publishes these as public: {packages}. Set `publishConfig.access` in each package.json"
700	+                ),
701	+            );
702	+        }
703	+    }
704	+    migration
705	+}
706	+
707	+impl Migration {
708	+    fn warn(&mut self, key: &str, message: &str) {
709	+        self.diagnostics.push(self.warning(format!("`{key}` {message}")));
710	+    }
711	+
712	+    fn warning(&self, message: String) -> Diagnostic {
713	+        Diagnostic {
714	+            code: DiagnosticCode::ChangesetsConfigKeyDropped,
715	+            severity: DiagnosticSeverity::Warning,
716	+            message,
717	+            package: None,
718	+            path: Some(self.path.clone()),
719	+            escalated_by: None,
720	+            governed_by: None,
721	+        }
722	+    }
723	+
724	+    fn translate_fixed(&mut self, value: &Value, facts: &InitFacts) {
725	+        let Ok(groups) = serde_json::from_value::<Vec<Vec<String>>>(value.clone()) else {
726	+            self.warn("fixed", "is not a list of lists of package names and is not translated");
727	+            return;
728	+        };
729	+        let npm: Vec<(&str, &str)> = facts
730	+            .packages
731	+            .iter()
732	+            .filter(|package| !package.platform)
733	+            .filter_map(|package| {
734	+                let name = package.id.strip_prefix(Ecosystem::Npm.prefix())?.strip_prefix('/')?;
735	+                Some((name, package.id.as_str()))
736	+            })
737	+            .collect();
738	+        for (index, patterns) in groups.iter().enumerate() {
739	+            let mut members: Vec<String> = Vec::new();
740	+            for pattern in patterns {
741	+                let matched: Vec<&str> = match GlobBuilder::new(pattern).literal_separator(true).build() {
742	+                    Ok(glob) => {
743	+                        let matcher = glob.compile_matcher();
744	+                        npm.iter()
745	+                            .filter(|(name, _)| matcher.is_match(name))
746	+                            .map(|(_, id)| *id)
747	+                            .collect()
748	+                    }
749	+                    Err(_) => Vec::new(),
750	+                };
751	+                if matched.is_empty() {
752	+                    self.fixed_unmatched.push(pattern.clone());
753	+                }
754	+                for id in matched {
755	+                    if !members.iter().any(|member| member == id) {
756	+                        members.push(id.to_owned());
757	+                    }
758	+                }
759	+            }
760	+            if !members.is_empty() {
761	+                self.fixed_groups.push(FixedGroup {
762	+                    name: format!("fixed-{}", index + 1),
763	+                    members,
764	+                });
765	+            }
766	+        }
767	+    }
768	+
769	+    /// Puts the carried-over `fixed` groups into `answers` and returns the warning that says what became of them.
770	+    pub fn apply_fixed_groups(&self, answers: &mut InitAnswers) -> Option<Diagnostic> {
771	+        if self.fixed_groups.is_empty() && self.fixed_unmatched.is_empty() {
772	+            return None;
773	+        }
774	+        let unmatched = if self.fixed_unmatched.is_empty() {
775	+            String::new()
776	+        } else {
777	+            let patterns: Vec<String> = self
778	+                .fixed_unmatched
779	+                .iter()
780	+                .map(|pattern| format!("`{pattern}`"))
781	+                .collect();
782	+            format!(" No npm package matches {}.", patterns.join(", "))
783	+        };
784	+        match answers.versioning {
785	+            Versioning::Fixed => Some(self.warning(format!(
786	+                "`fixed` is not translated: `--versioning fixed` already puts every package in one group.{unmatched}"
787	+            ))),
788	+            Versioning::Independent if self.fixed_groups.is_empty() => {
789	+                Some(self.warning(format!("`fixed` is not translated.{unmatched}")))
790	+            }
791	+            Versioning::Independent => {
792	+                answers.fixed_groups = self.fixed_groups.clone();
793	+                let names: Vec<&str> = self.fixed_groups.iter().map(|group| group.name.as_str()).collect();
794	+                Some(self.warning(format!(
795	+                    "`fixed` became `[[fixed-group]]` ({}), with each glob expanded to the npm packages that exist now: \
796	+                     add packages created later by hand.{unmatched}",
797	+                    names.join(", ")
798	+                )))
799	+            }
800	+        }
801	+    }
802	+
803	+    /// The warning for a `baseBranch` that no generated workflow consumes.
804	+    pub fn base_branch_unused(&self) -> Option<Diagnostic> {
805	+        let base = self.base_branch.as_ref()?;
806	+        Some(self.warning(format!(
807	+            "`baseBranch` `{base}` only sets the generated workflow's branch filter, and no workflow was generated; \
808	+             run `callisto init --workflow` to generate one"
809	+        )))
810	+    }
811	+}
